var Negotiator = require('./');

function assertEqual(actual, expected, msg){
  var ok = JSON.stringify(actual)===JSON.stringify(expected);
  console.log((ok?'PASS':'FAIL')+': '+msg);
  if(!ok) { console.log('  expected:', expected); console.log('  actual  :', actual); }
}

// Acceptance: With `Accept: text/html, application/json`, `mediaTypes(['text/html', 'application/json'], { preferred: ['application/json'] })` returns `['application/json', 'text/html']`, and `mediaType` with the same arguments returns `'application/json'`.
var req1 = { headers: { accept: 'text/html, application/json' } };
var n1 = new Negotiator(req1);
assertEqual(n1.mediaTypes(['text/html', 'application/json'], { preferred: ['application/json'] }), ['application/json','text/html'], 'mediaTypes preferred tie');
assertEqual(n1.mediaType(['text/html', 'application/json'], { preferred: ['application/json'] }), 'application/json', 'mediaType preferred tie');

// languages/language and charsets/charset take `{ preferred }` the same way: among equal q-values the preferred value comes first.
var req2 = { headers: { 'accept-language': 'en, fr' } };
var n2 = new Negotiator(req2);
assertEqual(n2.languages(['en','fr'], { preferred: ['fr'] }), ['fr','en'], 'languages preferred tie');
assertEqual(n2.language(['en','fr'], { preferred: ['fr'] }), 'fr', 'language preferred tie');

var req3 = { headers: { 'accept-charset': 'utf-8, iso-8859-1' } };
var n3 = new Negotiator(req3);
assertEqual(n3.charsets(['utf-8','iso-8859-1'], { preferred: ['iso-8859-1'] }), ['iso-8859-1','utf-8'], 'charsets preferred tie');
assertEqual(n3.charset(['utf-8','iso-8859-1'], { preferred: ['iso-8859-1'] }), 'iso-8859-1', 'charset preferred tie');

// A lower q-value still loses: with `Accept-Language: en, fr;q=0.5`, `languages(['en', 'fr'], { preferred: ['fr'] })` keeps `en` first.
var req4 = { headers: { 'accept-language': 'en, fr;q=0.5' } };
var n4 = new Negotiator(req4);
assertEqual(n4.languages(['en','fr'], { preferred: ['fr'] }), ['en','fr'], 'languages lower q loses even with preferred');
assertEqual(n4.languages(['fr','en'], { preferred: ['fr'] }), ['en','fr'], 'languages lower q loses even with preferred reversed input');
assertEqual(n4.language(['en','fr'], { preferred: ['fr'] }), 'en', 'language lower q loses');

// Calls without the option behave as before
assertEqual(n1.mediaTypes(['text/html','application/json']), ['text/html','application/json'], 'mediaTypes without preferred behaves as before');
assertEqual(n2.languages(['en','fr']), ['en','fr'], 'languages without preferred behaves as before');
assertEqual(n3.charsets(['utf-8','iso-8859-1']), ['utf-8','iso-8859-1'], 'charsets without preferred behaves as before');

// Additional: q tie with wildcard etc - ensure preferred overrides
var req5 = { headers: { accept: 'text/html, application/json' } };
var n5 = new Negotiator(req5);
assertEqual(n5.mediaTypes(['application/json','text/html'], { preferred: ['application/json'] }), ['application/json','text/html'], 'mediaTypes order independent of input when preferred');

// Encoding still works
var req6 = { headers: { 'accept-encoding': 'gzip, deflate' } };
var n6 = new Negotiator(req6);
assertEqual(n6.encodings(['gzip','deflate'], { preferred: ['deflate'] }), ['deflate','gzip'], 'encodings still works');

// Charset with q
var req7 = { headers: { 'accept-charset': 'utf-8;q=0.8, iso-8859-1' } };
var n7 = new Negotiator(req7);
assertEqual(n7.charsets(['utf-8','iso-8859-1']), ['iso-8859-1','utf-8'], 'charsets q sorting still works');
assertEqual(n7.charsets(['utf-8','iso-8859-1'], { preferred: ['utf-8'] }), ['iso-8859-1','utf-8'], 'charsets preferred does not override q');
assertEqual(n7.charsets(['utf-8','iso-8859-1'], { preferred: ['utf-8'] }).length, 2, 'charsets preferred length');

// Media type with different q
var req8 = { headers: { accept: 'text/html;q=0.5, application/json' } };
var n8 = new Negotiator(req8);
assertEqual(n8.mediaTypes(['text/html','application/json'], { preferred: ['text/html'] }), ['application/json','text/html'], 'mediaTypes preferred does not override q');

// Case insensitivity
var req9 = { headers: { accept: 'text/html, application/json' } };
var n9 = new Negotiator(req9);
assertEqual(n9.mediaTypes(['text/html','application/json'], { preferred: ['APPLICATION/JSON'] }), ['application/json','text/html'], 'mediaTypes preferred case insensitive');

var req10 = { headers: { 'accept-language': 'EN, fr' } };
var n10 = new Negotiator(req10);
assertEqual(n10.languages(['en','fr'], { preferred: ['FR'] }), ['fr','en'], 'languages preferred case insensitive');

var req11 = { headers: { 'accept-charset': 'UTF-8, ISO-8859-1' } };
var n11 = new Negotiator(req11);
assertEqual(n11.charsets(['utf-8','iso-8859-1'], { preferred: ['ISO-8859-1'] }), ['iso-8859-1','utf-8'], 'charsets preferred case insensitive');

// Direct lib call test
var preferredMediaTypes = require('./lib/mediaType');
assertEqual(preferredMediaTypes('text/html, application/json', ['text/html','application/json'], ['application/json']), ['application/json','text/html'], 'lib/mediaType direct call');

var preferredLanguages = require('./lib/language');
assertEqual(preferredLanguages('en, fr', ['en','fr'], ['fr']), ['fr','en'], 'lib/language direct call');

var preferredCharsets = require('./lib/charset');
assertEqual(preferredCharsets('utf-8, iso-8859-1', ['utf-8','iso-8859-1'], ['iso-8859-1']), ['iso-8859-1','utf-8'], 'lib/charset direct call');

console.log('done');
